\title{A Rigorous Finite-Size Theory of Landauer's Principle:\\
From the Jarzynski Equality to Logical Irreversibility}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop, from first principles over finite probability spaces, a complete and
self-contained mathematical theory of Landauer's principle---the statement that
erasing one bit of information dissipates at least $kT\ln 2$ of work. Starting only
from elementary inequalities ($1+x\le e^x$ and $\ln x \le x-1$) and the finite
Jarzynski equality $\E[e^{-\alpha W}] = e^{-\alpha\,\Delta F}$, we prove: an exact
finite-size Landauer identity expressing the mean dissipated work as the
free-energy difference plus a nonnegative fluctuation correction; the average
second law $\Delta F \le \E[W]$ and the single-bit bound $kT\ln 2 \le \E[W]$; a
saturation theorem showing the bound is attained exactly in the reversible limit;
an integral fluctuation theorem bounding second-law violations by $e^{-\xi/(kT)}$;
the extensivity of the bound, $n\,kT\ln 2$ for an $n$-bit register, with exact
per-bit cost $kT\ln 2$; a dual relative-entropy account via Gibbs' inequality with
a maximum-entropy bound; a deterministic data-processing inequality identifying
reversible computation as the zero-dissipation boundary; and a bridge theorem
showing that logical irreversibility forces thermodynamic irreversibility.
\end{abstract}

\section{Introduction}
In 1961 Rolf Landauer proposed that any \emph{logically irreversible} operation,
one that maps distinct logical states to a common state, must be accompanied by
heat dissipation. The canonical example is the erasure (``reset to zero'') of a
single bit, whose minimal cost is
\[
  \E[W] \ge kT\ln 2,
\]
where $k$ is Boltzmann's constant and $T$ the absolute temperature. The principle
resolves the paradox of Maxwell's demon and sets a fundamental floor on the energy
efficiency of computation. At the nanoscale erasure is a genuinely nonequilibrium,
fluctuating process: the work $W$ in a single realization is a random variable. We
present a rigorous, minimal-axiom development of Landauer's principle as a
consequence of the finite Jarzynski equality, valid for memories of arbitrary
finite size, and make explicit the logical-to-thermodynamic bridge.

\section{Related Work and Contribution}
Landauer (1961) and Bennett (1982) established the principle and its role in the
thermodynamics of computation; Jarzynski (1997) proved the nonequilibrium work
equality; Esposito and Van den Broeck (2011) recast the second law and Landauer's
principle in relative-entropy form; Plenio and Vitelli (2001) surveyed the
information-theoretic content. Our contribution is a complete first-principles
synthesis in which every statement is derived from explicit finite sums and two
scalar inequalities, isolating the precise senses in which $kT\ln 2$ is an
average, is saturated only reversibly, and is forced by a combinatorial fact.

\section{The finite-probability framework}
We work over a finite type $\Omega$ of microstates.

\begin{definition}[Expectation]
For weight $p:\Omega\to\mathbb{R}$ and observable $f:\Omega\to\mathbb{R}$,
$\E_p[f] = \sum_{\omega} p(\omega)\,f(\omega)$.
\end{definition}

\begin{definition}[PMF]
$p$ is a PMF, $\IsPMF(p)$, if $p(\omega)\ge 0$ for all $\omega$ and
$\sum_\omega p(\omega) = 1$.
\end{definition}

\begin{definition}[Shannon entropy]
With $\negMulLog(x) = -x\ln x$ (so $\negMulLog(0)=0$),
$H(p) = \sum_\omega \negMulLog(p(\omega)) = -\sum_\omega p(\omega)\ln p(\omega)$.
\end{definition}

\begin{definition}[Finite Jarzynski equality]
For work $W$, inverse temperature $\alpha$, and free-energy difference $\Delta F$,
the condition $\mathrm{Jarzynski}(p,W,\alpha,\Delta F)$ holds when
$\E_p[e^{-\alpha W}] = e^{-\alpha\,\Delta F}$.
\end{definition}

\begin{definition}[Relative entropy]
$\KL(p\,\|\,q) = \sum_\omega p(\omega)\ln\frac{p(\omega)}{q(\omega)}$; the factor
$p(\omega)$ makes $0\ln 0 = 0$ automatic.
\end{definition}

The bit-level distributions are the uniform bit $u(b)=\tfrac12$, the erased bit
$e(0)=1, e(1)=0$, and the erasure map $\er(b)=0$.

\section{The entropic cost of erasure}
\begin{proposition}[Uniform bit] $H(u) = \ln 2$. \end{proposition}
\begin{proof}[Sketch] Both summands equal $\tfrac12\ln 2$. \end{proof}

\begin{proposition}[Erased bit] $H(e) = 0$. \end{proposition}
\begin{proof}[Sketch] The mass-$1$ and mass-$0$ outcomes both contribute $0$. \end{proof}

\begin{theorem}[Entropy loss] $H(u) - H(e) = \ln 2$. \end{theorem}

\begin{proposition}[Logical irreversibility]
The erasure map $\er$ is not injective: $\er(0)=\er(1)=0$ while $0\ne 1$.
\end{proposition}

\section{The Jarzynski correction and the average second law}

\begin{theorem}[Jarzynski fluctuation correction]
If $p$ is a PMF, $\alpha\ne 0$, and $\mathrm{Jarzynski}(p,W,\alpha,\Delta F)$, then
\[
  \E_p[W] = \Delta F + \frac{1}{\alpha}\,\ln \E_p\!\left[e^{-\alpha(W-\E_p[W])}\right].
\]
\end{theorem}
\begin{proof}[Sketch]
Write $e^{-\alpha(W-\E_p[W])} = e^{\alpha\E_p[W]}e^{-\alpha W}$, pull the constant
out of the expectation, apply the Jarzynski equality to get
$e^{\alpha(\E_p[W]-\Delta F)}$, take logarithms and divide by $\alpha$.
\end{proof}

\begin{corollary}[Finite-size Landauer identity]
With $\Delta F = (H(u)-H(e))/\alpha = \ln 2/\alpha$,
$\E_p[W] = \frac{H(u)-H(e)}{\alpha} + \frac{1}{\alpha}\ln\E_p[e^{-\alpha(W-\E_p[W])}]$.
\end{corollary}

\begin{lemma}[Finite Jensen bound]
For any PMF $p$ and observable $g$, $1+\E_p[g] \le \E_p[e^g]$.
\end{lemma}
\begin{proof}[Sketch]
Apply $1+x\le e^x$ pointwise, weight by $p(\omega)\ge0$, and sum; the left side
collapses to $1+\E_p[g]$ using $\sum p = 1$.
\end{proof}

\begin{lemma}[Centered work] $\E_p[-\alpha(W-\E_p[W])] = 0$. \end{lemma}

\begin{theorem}[Fluctuation factor $\ge 1$]
$\E_p[e^{-\alpha(W-\E_p[W])}] \ge 1$.
\end{theorem}
\begin{proof}[Sketch] Combine the two preceding lemmas with $g=-\alpha(W-\E_p[W])$. \end{proof}

\begin{corollary}[Nonnegative correction]
$\ln\E_p[e^{-\alpha(W-\E_p[W])}] \ge 0$.
\end{corollary}

\begin{theorem}[Average second law]
If $\alpha>0$ and $\mathrm{Jarzynski}(p,W,\alpha,\Delta F)$, then
$\Delta F \le \E_p[W]$.
\end{theorem}
\begin{proof}[Sketch]
Substitute the correction identity; the correction is $\alpha^{-1}>0$ times a
nonnegative logarithm.
\end{proof}

\begin{theorem}[Landauer's $kT\ln2$ bound]
For $k,T>0$ with $\alpha=(kT)^{-1}$, $\Delta F=kT\ln 2$, one has
$kT\ln 2 \le \E_p[W]$.
\end{theorem}

\begin{theorem}[Cost--entropy-loss bridge]
$kT\ln 2 = kT\,(H(u)-H(e))$.
\end{theorem}

\section{Saturation: the reversible limit}
\begin{lemma}[Strict Jensen bound]
If $g(\omega)\ne0$ for some $\omega$ with $p(\omega)>0$, then
$1+\E_p[g] < \E_p[e^g]$.
\end{lemma}

\begin{theorem}[Equality case]
For $\alpha\ne0$, $\E_p[e^{-\alpha(W-\E_p[W])}]=1$ iff $W$ is constant on the
support of $p$ (i.e.\ $p(\omega)>0 \Rightarrow W(\omega)=\E_p[W]$).
\end{theorem}

\begin{theorem}[Strict second law]
If $\alpha>0$, $\mathrm{Jarzynski}(p,W,\alpha,\Delta F)$, and $W$ fluctuates on the
support, then $\Delta F < \E_p[W]$.
\end{theorem}

\begin{theorem}[Landauer saturation $\iff$ reversibility]
For $k,T>0$ and $\Delta F=kT\ln 2$, $kT\ln 2 = \E_p[W]$ iff $W$ is constant on the
support of $p$.
\end{theorem}

\section{Fluctuation theorem: bounding second-law violations}
\begin{theorem}[Exponential violation bound]
If $\alpha>0$ and $\mathrm{Jarzynski}(p,W,\alpha,\Delta F)$, then for any $\xi$,
\[
  \sum_{\omega:\,W(\omega)<\Delta F-\xi} p(\omega) \le e^{-\alpha\xi}.
\]
\end{theorem}
\begin{proof}[Sketch]
Restrict the Jarzynski sum to the violation set $S$; nonnegativity gives
$\sum_S p(\omega)e^{-\alpha W(\omega)} \le e^{-\alpha\Delta F}$. On $S$,
$e^{-\alpha W(\omega)} > e^{-\alpha(\Delta F-\xi)}$, so
$(\sum_S p)\,e^{-\alpha(\Delta F-\xi)} \le e^{-\alpha\Delta F}$.
\end{proof}

\begin{theorem}[No certain violation]
If $\xi\ge0$ and some $\omega_0$ has $p(\omega_0)>0$, $W(\omega_0)\ge\Delta F$,
then $\sum_{\omega:\,W(\omega)<\Delta F-\xi}p(\omega) < 1$.
\end{theorem}

\begin{theorem}[Landauer violation bound]
For one-bit erasure, $\sum_{\omega:\,W(\omega)<kT\ln 2-\xi}p(\omega) \le e^{-\xi/(kT)}$.
\end{theorem}

\begin{theorem}[Monotone decay]
For $k,T>0$ and $\xi_1<\xi_2$, $e^{-\xi_2/(kT)} < e^{-\xi_1/(kT)}$.
\end{theorem}

\section{Extensivity: the thermodynamic limit}
\begin{theorem}[Uniform $N$-state entropy]
If $|\Omega|=N>0$, the uniform PMF has $H = \ln N$.
\end{theorem}

\begin{theorem}[Maximal $n$-bit entropy]
With $|\Omega|=2^n$, the uniform PMF has $H = n\ln 2$.
\end{theorem}

\begin{theorem}[Extensive Landauer bound]
For an $n$-bit memory at $k,T>0$ with $\Delta F=n\,kT\ln 2$,
$n\,kT\ln 2 \le \E_p[W]$.
\end{theorem}

\begin{theorem}[Exact per-bit cost]
For $n>0$, $\dfrac{n\,kT\ln 2}{n} = kT\ln 2$.
\end{theorem}

\section{The relative-entropy account and maximum entropy}
\begin{theorem}[Self-divergence] $\KL(p\,\|\,p)=0$. \end{theorem}

\begin{theorem}[Gibbs' inequality]
For PMFs $p,q$ with $q(\omega)>0$ for all $\omega$, $\KL(p\,\|\,q)\ge0$.
\end{theorem}
\begin{proof}[Sketch]
From $\ln x \le x-1$ at $x=q(\omega)/p(\omega)$,
$p(\omega)\ln\frac{p(\omega)}{q(\omega)} \ge p(\omega)-q(\omega)$; summing gives
$\KL \ge \sum_\omega(p(\omega)-q(\omega)) = 1-1 = 0$.
\end{proof}

\begin{theorem}[Erased-vs-uniform] $\KL(e\,\|\,u) = \ln 2$. \end{theorem}

\begin{theorem}[Unification] $\KL(e\,\|\,u) = H(u)-H(e)$. \end{theorem}

\begin{theorem}[Cost as relative entropy]
$kT\ln 2 = kT\,\KL(e\,\|\,u)$, and $0\le kT\,\KL(p\,\|\,q)$ for $q>0$, $k,T\ge0$.
\end{theorem}

\begin{theorem}[Entropy--relative-entropy identity]
For any PMF $p$ on an $N$-state space with uniform reference $u_N$,
$H(p) = \ln N - \KL(p\,\|\,u_N)$.
\end{theorem}

\begin{theorem}[Maximum-entropy bound]
For any PMF $p$ on an $N$-state space, $H(p) \le \ln N$, with equality for $u_N$.
\end{theorem}

\begin{theorem}[Generalized Landauer bound]
For initial PMF $p$ erased at $\Delta F = kT\,H(p)$ with $k,T>0$,
$kT\,H(p) \le \E_p[W]$.
\end{theorem}

\begin{theorem}[Uniform memory is worst-case]
For $k,T\ge0$, $kT\,H(p) \le kT\ln N$.
\end{theorem}

\section{Data processing and the logical-to-thermodynamic bridge}
For a deterministic map $f$ with pushforward
$(f_*p)(y) = \sum_{x:\,f(x)=y} p(x)$:

\begin{theorem}[Data-processing inequality]
For nonnegative weights $p$, $H(f_*p) \le H(p)$.
\end{theorem}
\begin{proof}[Sketch]
Reindex $H(f_*p) = -\sum_x p(x)\ln (f_*p)(f(x))$. Since $(f_*p)(f(x))\ge p(x)\ge0$
and $\ln$ is monotone, each term satisfies $p(x)\ln p(x) \le p(x)\ln(f_*p)(f(x))$.
\end{proof}

\begin{theorem}[Reversibility preserves entropy]
If $f$ is injective, $H(f_*p) = H(p)$.
\end{theorem}

\begin{theorem}[Landauer lower bound for computation]
For $k,T\ge0$, $0 \le kT\,(H(p)-H(f_*p))$, with equality when $f$ is injective.
\end{theorem}

\begin{theorem}[Logical irreversibility forces thermodynamic irreversibility]
For a one-bit memory at $k,T>0$ with $\Delta F=kT\ln 2$ and
$\mathrm{Jarzynski}(p,W,(kT)^{-1},kT\ln 2)$,
\[
  \er\ \text{is not injective} \quad\wedge\quad 0 < \E_p[W].
\]
\end{theorem}
\begin{proof}[Sketch]
Non-injectivity is the combinatorial proposition above; $kT\ln 2\le\E_p[W]$ from
the Landauer bound and $kT\ln 2>0$ give strict positivity.
\end{proof}

\section{Discussion}
The extensive bound sets a floor of $R\,kT\ln 2$ watts on a processor performing
$R$ irreversible bit-erasures per second; reversible computing defers this cost to
the final memory reset; and the bridge theorem is the modern resolution of
Maxwell's demon---the demon repays $kT\ln 2$ per recorded bit upon erasing its
memory. The finite-size identity, saturation, and violation bound are precisely
the statements probed in single-bit erasure experiments.

\section{Future directions}
A correlated-erasure extension introduces mutual information $I(X;Y) = H(X)+H(Y)-H(X,Y)$,
subadditivity, and a $kT\,I(X;Y)$ correlation saving for joint erasure. Natural
conjectures are: strong subadditivity $H(X,Y,Z)+H(Y)\le H(X,Y)+H(Y,Z)$; a
conditional Landauer bound $kT\,H(X\mid Y)$; saturation of subadditivity iff
independence; the data-processing inequality for relative entropy
$\KL(Tp\,\|\,Tq)\le\KL(p\,\|\,q)$; and a mutual-information fluctuation theorem
bounding the failure probability of the $kT\,I(X;Y)$ saving by $e^{-\xi/(kT)}$.

\section{Conclusion}
The single-bit bound $kT\ln 2$ emerges as the average case of an exact fluctuation
identity, saturated only reversibly, protected by an exponential fluctuation
theorem, scaling extensively to $n\,kT\ln 2$, dual to a relative-entropy /
maximum-entropy account, and forced by the non-injectivity of erasure. The whole
edifice rests on $1+x\le e^x$ and $\ln x\le x-1$ together with the finite
Jarzynski equality.

