function RELATIVE-ENTROPY(p, q):
  total <- 0
  for omega in support(p):
    if p[omega] > 0: total <- total + p[omega]*ln(p[omega]/q[omega])
  return total            # >= 0 by Gibbs when q has full support

function MAX-ENTROPY-GAP(p, N):
  return ln(N) - SHANNON-ENTROPY(p)   # = D(p || uniform_N) >= 0

