function VIOLATION-BOUND-CHECK(p, W, alpha, DeltaF, xi):
  empirical <- sum of p[omega] over { omega : W[omega] < DeltaF - xi }
  ceiling   <- exp(-alpha * xi)
  assert empirical <= ceiling      # integral fluctuation theorem
  return (empirical, ceiling, ceiling - empirical)
